mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("(id0,t0,d3),(id1,t1,d1),(id2,t1,d2)","0,1,2"),
        ("(id0,t0,d2),(id1,t0,d1),(id2,t3,d1)","1,0,2"),
        ("(id0,t0,d1),(id1,t0,d1)","0,1"),
        ("(id0,t5,d2),(id1,t8,d1)","0,1"),
        ("(id0,t0,d4),(id1,t1,d1),(id2,t2,d1)","0,1,2"),
        ("  \n(id0,t0,d3),(id1,t1,d1),(id2,t1,d2)\n  ","0,1,2"),
        ("\n(id0,t0,d4),(id1,t1,d1),(id2,t2,d1)\n","0,1,2")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS priority-scheduling");
}
